namespace {
String bn(const String&p){int s=p.lastIndexOf('/');return s>=0?p.substring(s+1):p;}
String stem(String p){p=bn(p);if(p.endsWith(".bin"))p.remove(p.length()-4);return p;}
String clean(String n){n.trim();if(n.endsWith(".bin"))n.remove(n.length()-4);for(int i=0;i<(int)n.length();++i){char c=n[i];bool ok=(c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_';if(!ok)n.setCharAt(i,'_');}while(n.indexOf("__")>=0)n.replace("__","_");return n;}
String uniquePath(const String&dir,const String&base){String p=dir+"/"+base+".bin";if(!Uni.Storage->exists(p.c_str()))return p;for(int n=2;n<1000;++n){p=dir+"/"+base+"_("+String(n)+").bin";if(!Uni.Storage->exists(p.c_str()))return p;}return "";}
bool parseHex(String t,uint8_t*out,size_t n){t.replace(" ","");t.replace(":","");if(t.length()!=n*2)return false;auto x=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='A'&&c<='F')return c-'A'+10;if(c>='a'&&c<='f')return c-'a'+10;return -1;};for(size_t i=0;i<n;++i){int a=x(t[i*2]),b=x(t[i*2+1]);if(a<0||b<0)return false;out[i]=(a<<4)|b;}return true;}
bool passwordFromText(const String&text,uint8_t pwd[4]){if(!text.length())return false;const mbedtls_md_info_t*md=mbedtls_md_info_from_type(MBEDTLS_MD_MD5);if(!md)return false;uint8_t digest[16]={};if(mbedtls_md(md,reinterpret_cast<const unsigned char*>(text.c_str()),text.length(),digest)!=0)return false;memcpy(pwd,digest,4);return true;}
const char* shortType(HfDumpParser::Type t){switch(t){case HfDumpParser::TYPE_MIFARE_CLASSIC_1K:return "MF-1K";case HfDumpParser::TYPE_MIFARE_CLASSIC_4K:return "MF-4K";case HfDumpParser::TYPE_NTAG210:return "NTAG210";case HfDumpParser::TYPE_NTAG212:return "NTAG212";case HfDumpParser::TYPE_NTAG213:return "NTAG213";case HfDumpParser::TYPE_NTAG215:return "NTAG215";case HfDumpParser::TYPE_NTAG216:return "NTAG216";default:return "HF";}}
uint16_t ntagConfig0(HfDumpParser::Type t){switch(t){case HfDumpParser::TYPE_NTAG210:return 16;case HfDumpParser::TYPE_NTAG212:return 37;case HfDumpParser::TYPE_NTAG213:return 41;case HfDumpParser::TYPE_NTAG215:return 131;case HfDumpParser::TYPE_NTAG216:return 227;default:return 0xFFFF;}}
uint16_t ntagDynamicLockPage(HfDumpParser::Type t){switch(t){case HfDumpParser::TYPE_NTAG212:return 36;case HfDumpParser::TYPE_NTAG213:return 40;case HfDumpParser::TYPE_NTAG215:return 130;case HfDumpParser::TYPE_NTAG216:return 226;default:return 0xFFFF;}}
const char* ntagSensitivePageLabel(HfDumpParser::Type t,uint16_t page){uint16_t dl=ntagDynamicLockPage(t),c=ntagConfig0(t);if(page==dl)return "Dynamic lock page";if(page==c||page==c+1)return "Configuration page";if(page==c+2)return "Password page";if(page==c+3)return "PACK page";return nullptr;}
bool confirmNtagSensitiveWrite(HfDumpParser::Type t,uint16_t page){const char*l=ntagSensitivePageLabel(t,page);if(!l)return true;static const InputSelectAction::Option o[]={{"Write anyway","write"}};String title=String("Warning: ")+l;const char*c=InputSelectAction::popup(title.c_str(),o,1,nullptr);return c&&strcmp(c,"write")==0;}
}

const char* HfDumpLibraryScreen::title(){return _state==BROWSE?"Saved HF Dumps":(_state==DETAILS?"HF Dump Details":"HF Dump Actions");}
void HfDumpLibraryScreen::onInit(){_browser.root=_dir;open();}
void HfDumpLibraryScreen::open(){_state=BROWSE;if(!Uni.Storage||!Uni.Storage->isAvailable()){ShowStatusAction::show("Storage unavailable",1600);Screen.goBack();return;}Uni.Storage->makeDir("/unigeek/nfc");Uni.Storage->makeDir(_dir.c_str());setItems(_browser.items(),_browser.load(this,_browseDir,".bin","DUMP",BrowseFileView::STEM));}
bool HfDumpLibraryScreen::inspect(const String&p){if(!Uni.Storage||!Uni.Storage->isAvailable())return false;fs::File f=Uni.Storage->open(p.c_str(),"r");if(!f)return false;size_t n=f.size();if(!n||n>4096){f.close();return false;}uint8_t*b=new(std::nothrow)uint8_t[n];if(!b){f.close();return false;}bool ok=f.read(b,n)==n;f.close();if(ok){_info=HfDumpParser::inspect(b,n);ok=_info.type!=HfDumpParser::TYPE_UNKNOWN;}delete[]b;return ok;}
void HfDumpLibraryScreen::details(){_state=DETAILS;_dc=0;auto add=[&](String l,String v){_dl[_dc]=l;_dv[_dc]=v;_details[_dc]={_dl[_dc].c_str(),_dv[_dc]};++_dc;};add("File",bn(_path));add("Type",HfDumpParser::typeName(_info.type));String u;for(uint8_t i=0;i<_info.uidLen;++i){char h[3];snprintf(h,sizeof(h),"%02X",_info.uid[i]);u+=h;}add("UID",u.length()?u:"Unknown");add("Size",String((unsigned)_info.size)+" bytes");add("NDEF",_info.hasNdef?"Yes":"No");_details[_dc++]={"[Press]","Actions"};_detailsView.resetScroll();_detailsView.setRows(_details,_dc);render();}
void HfDumpLibraryScreen::onItemSelected(uint8_t i){if(_state==BROWSE){if(i>=_browser.count())return;auto e=_browser.entry(i);if(e.isDir){_browseDir=e.path;open();return;}if(!inspect(e.path)){ShowStatusAction::show("Dump format not supported",1600);return;}_path=e.path;details();return;}if(_state==DETAILS){_state=ACTIONS;setItems(_actions);return;}Screen.push(new HfDumpFormScreen(i==0?HfDumpFormScreen::COPY_ITEM:HfDumpFormScreen::EDIT_ITEM,_path));}
void HfDumpLibraryScreen::onBack(){if(_state==ACTIONS){details();return;}if(_state==DETAILS){open();return;}Screen.goBack();}
void HfDumpLibraryScreen::onUpdate(){if(_state!=DETAILS){ListScreen::onUpdate();return;}if(!Uni.Nav->wasPressed())return;auto d=Uni.Nav->readDirection();if(d==INavigation::DIR_BACK){open();return;}if(d==INavigation::DIR_PRESS){_state=ACTIONS;setItems(_actions);return;}_detailsView.onNav(d);}
void HfDumpLibraryScreen::onRender(){if(_state==DETAILS){_detailsView.render(bodyX(),bodyY(),bodyW(),bodyH());return;}ListScreen::onRender();}

HfDumpFormScreen::HfDumpFormScreen(Mode m,const String&p):_mode(m),_path(p){}
HfDumpFormScreen::~HfDumpFormScreen(){freeDump();}
void HfDumpFormScreen::freeDump(){delete[]_dump;_dump=nullptr;_dumpLen=0;}
bool HfDumpFormScreen::load(const String&p){if(!Uni.Storage||!Uni.Storage->isAvailable())return false;fs::File f=Uni.Storage->open(p.c_str(),"r");if(!f)return false;size_t n=f.size();if(!n||n>4096){f.close();return false;}uint8_t*b=new(std::nothrow)uint8_t[n];if(!b){f.close();return false;}if(f.read(b,n)!=n){f.close();delete[]b;return false;}f.close();auto info=HfDumpParser::inspect(b,n);if(info.type==HfDumpParser::TYPE_UNKNOWN){delete[]b;return false;}freeDump();_dump=b;_dumpLen=n;_info=info;_uidLen=info.uidLen;memcpy(_uid,info.uid,_uidLen);_uidSource=UID_CURRENT;uint8_t*nd=nullptr;size_t nl=0;if(HfDumpParser::extractNdef(_dump,_dumpLen,&nd,&nl)&&nd&&nl<=sizeof(_ndef)){memcpy(_ndef,nd,nl);_ndefLen=nl;_ndefSource=NDEF_CURRENT;}else{_ndefLen=0;_ndefSource=NDEF_NONE;}delete[]nd;return true;}
void HfDumpFormScreen::onInit(){if(_mode!=NEW_ITEM&&_path.length()){if(!load(_path)){ShowStatusAction::show("Dump format not supported",1600);Screen.goBack();return;}if(_mode==COPY_ITEM)_path="";}else if(!buildDefault(5)){ShowStatusAction::show("Failed",1600);Screen.goBack();return;}rebuild();}
void HfDumpFormScreen::randomUid(){if(_uidLen==7){_uid[0]=0x04;for(uint8_t i=1;i<7;++i)_uid[i]=(uint8_t)esp_random();}else for(uint8_t i=0;i<_uidLen;++i)_uid[i]=(uint8_t)esp_random();}
bool HfDumpFormScreen::buildDefault(uint8_t ti){size_t cap=0;_uidLen=(ti<2)?4:7;randomUid();if(ti==0)cap=HfDumpBuilder::MIFARE_CLASSIC_1K_SIZE;else if(ti==1)cap=HfDumpBuilder::MIFARE_CLASSIC_4K_SIZE;else {static const size_t sz[]={HfDumpBuilder::NTAG210_SIZE,HfDumpBuilder::NTAG212_SIZE,HfDumpBuilder::NTAG213_SIZE,HfDumpBuilder::NTAG215_SIZE,HfDumpBuilder::NTAG216_SIZE};cap=sz[ti-2];}uint8_t*b=new(std::nothrow)uint8_t[cap];if(!b)return false;size_t n=0;bool ok=false;if(ti==0)ok=HfDumpBuilder::buildMifareClassic1K(_uid,nullptr,0,b,n,cap);else if(ti==1)ok=HfDumpBuilder::buildMifareClassic4K(_uid,nullptr,0,b,n,cap);else ok=HfDumpBuilder::buildNtag21x((HfDumpBuilder::Ntag21xType)(ti-2),_uid,nullptr,0,b,n,cap);if(!ok){delete[]b;return false;}freeDump();_dump=b;_dumpLen=n;_info=HfDumpParser::inspect(b,n);_uidSource=UID_RANDOM;_ndefSource=NDEF_NONE;_ndefLen=0;_uidFile="";_ndefFile="";return true;}
bool HfDumpFormScreen::rebuildForType(uint8_t ti){return buildDefault(ti);}
String HfDumpFormScreen::uidText()const{String s;for(uint8_t i=0;i<_uidLen;++i){char h[3];snprintf(h,sizeof(h),"%02X",_uid[i]);s+=h;}return s;}
void HfDumpFormScreen::rebuild(){_passwordView=false;_state=FORM;uint8_t sel=_selectedIndex;_count=0;auto add=[&](const char*l,const String&v){_values[_count]=v;_items[_count]={l,_values[_count].c_str()};++_count;};add("Type",HfDumpParser::typeName(_info.type));const char*us=_uidSource==UID_RANDOM?"Random":_uidSource==UID_CURRENT?"Current":_uidSource==UID_SAVED?"File":"Manual";add("UID",us);if(_uidSource==UID_SAVED)add("UID File",_uidFile.length()?stem(_uidFile):"-");if(_uidSource==UID_MANUAL||_uidSource==UID_CURRENT)add("UID Value",uidText());const char*ns=_ndefSource==NDEF_NONE?"None":_ndefSource==NDEF_CURRENT?"Current":_ndefSource==NDEF_SAVED?"File":"New";add("NDEF",ns);if(_ndefSource==NDEF_SAVED)add("NDEF File",_ndefFile.length()?stem(_ndefFile):"-");_items[_count++]={"Read Memory",nullptr};_items[_count++]={"Edit Memory",nullptr};if(HfDumpParser::isType2(_info.type)){_items[_count++]={"Password Info",nullptr};_items[_count++]={"Set Password",nullptr};_items[_count++]={"Remove Password",nullptr};}_items[_count++]={"Save",nullptr};setItems(_items,_count,min<uint8_t>(sel,_count-1));}
void HfDumpFormScreen::selectType(){_state=TYPE_SELECT;setItems(_types,7);}
void HfDumpFormScreen::selectUidSource(){_state=UID_SOURCE_SELECT;if(_mode==NEW_ITEM&&!_path.length()&&_uidSource!=UID_CURRENT)setItems(_uidSourcesNew,3);else setItems(_uidSourcesExisting,4);}
void HfDumpFormScreen::browseUid(){if(!Uni.Storage||!Uni.Storage->isAvailable()){rebuild();ShowStatusAction::show("Storage unavailable",1600);return;}_state=UID_FILE_SELECT;_browser.root="/unigeek/nfc/uids";if(!_uidPickDir.startsWith(_browser.root))_uidPickDir=_browser.root;setItems(_browser.items(),_browser.load(this,_uidPickDir,".uid",nullptr,BrowseFileView::STEM));}
void HfDumpFormScreen::selectNdefSource(){_state=NDEF_SOURCE_SELECT;if(_mode==NEW_ITEM&&!_path.length()&&_ndefSource!=NDEF_CURRENT)setItems(_ndefSourcesNew,3);else setItems(_ndefSourcesExisting,4);}
void HfDumpFormScreen::browseNdef(){if(!Uni.Storage||!Uni.Storage->isAvailable()){rebuild();ShowStatusAction::show("Storage unavailable",1600);return;}_state=NDEF_FILE_SELECT;_browser.root="/unigeek/nfc/ndefs";if(!_ndefPickDir.startsWith(_browser.root))_ndefPickDir=_browser.root;setItems(_browser.items(),_browser.load(this,_ndefPickDir,".ndef",nullptr,BrowseFileView::STEM));}
bool HfDumpFormScreen::applyUid(){return HfDumpParser::setUid(_dump,_dumpLen,_uid,_uidLen);}
bool HfDumpFormScreen::applyNdef(){if(_ndefSource==NDEF_NONE)return HfDumpParser::replaceNdef(_dump,_dumpLen,nullptr,0);if(_ndefLen==0)return false;return HfDumpParser::replaceNdef(_dump,_dumpLen,_ndef,_ndefLen);}
void HfDumpFormScreen::editUid(){String t=InputTextAction::popup("UID (hex)",uidText().c_str(),InputTextAction::INPUT_HEX);if(InputTextAction::wasCancelled()){rebuild();return;}uint8_t u[10]={};if(!parseHex(t,u,_uidLen)){rebuild();ShowStatusAction::show((String("UID must be ")+String(_uidLen*2)+" hex digits").c_str(),1600);return;}uint8_t old[10]={};memcpy(old,_uid,_uidLen);memcpy(_uid,u,_uidLen);if(!applyUid()){memcpy(_uid,old,_uidLen);rebuild();ShowStatusAction::show("UID format not supported",1600);return;}else _info=HfDumpParser::inspect(_dump,_dumpLen);rebuild();}
void HfDumpFormScreen::viewMemory(){if(!_dump||!_dumpLen){rebuild();return;}const auto layout=HfDumpParser::isMifareClassic(_info.type)?NfcMemoryViewScreen::MIFARE_CLASSIC:NfcMemoryViewScreen::TYPE2;Screen.push(new NfcMemoryViewScreen(layout,HfDumpParser::typeName(_info.type),_info.uid,_info.uidLen,_dump,_dumpLen));}
void HfDumpFormScreen::editMemory(){if(HfDumpParser::isMifareClassic(_info.type)){size_t blocks=_dumpLen/16;if(blocks<=1)return;int b=InputNumberAction::popup((String("Block (1..")+String((unsigned)(blocks-1))+")").c_str(),1,(int)blocks-1,1);if(InputNumberAction::wasCancelled()){rebuild();return;}String cur;for(int j=0;j<16;++j){char h[3];snprintf(h,sizeof(h),"%02X",_dump[b*16+j]);cur+=h;}String t=InputTextAction::popup("Block data (32 hex)",cur.c_str(),InputTextAction::INPUT_HEX);uint8_t d[16];if(!InputTextAction::wasCancelled()&&parseHex(t,d,16))memcpy(_dump+b*16,d,16);else if(!InputTextAction::wasCancelled()){rebuild();ShowStatusAction::show("Enter 32 hex characters",1600);return;}}else if(HfDumpParser::isType2(_info.type)){size_t pages=_dumpLen/4;int p=InputNumberAction::popup((String("Page (4..")+String((unsigned)(pages-1))+")").c_str(),4,(int)pages-1,4);if(InputNumberAction::wasCancelled()){rebuild();return;}String cur;for(int j=0;j<4;++j){char h[3];snprintf(h,sizeof(h),"%02X",_dump[p*4+j]);cur+=h;}String t=InputTextAction::popup("Page data (8 hex)",cur.c_str(),InputTextAction::INPUT_HEX);uint8_t d[4];if(!InputTextAction::wasCancelled()&&parseHex(t,d,4)){if(confirmNtagSensitiveWrite(_info.type,(uint16_t)p))memcpy(_dump+p*4,d,4);}else if(!InputTextAction::wasCancelled()){rebuild();ShowStatusAction::show("Enter 8 hex characters",1600);return;}}_info=HfDumpParser::inspect(_dump,_dumpLen);memcpy(_uid,_info.uid,_info.uidLen);_uidLen=_info.uidLen;rebuild();}
void HfDumpFormScreen::showPasswordInfo(){const auto p=HfDumpParser::inspectPassword(_dump,_dumpLen);if(!p.supported){rebuild();ShowStatusAction::show("Password not supported",1600);return;}_passwordView=true;_passwordCount=0;auto row=[&](const String&l,const String&v){_passwordLabels[_passwordCount]=l;_passwordValues[_passwordCount]=v;_passwordRows[_passwordCount]={_passwordLabels[_passwordCount].c_str(),_passwordValues[_passwordCount].c_str()};++_passwordCount;};row("Protection",p.enabled?"Enabled":"Disabled");char h[8];snprintf(h,sizeof(h),"%02X",p.auth0);row("AUTH0",h);row("Access",p.protectRead?"Read & Write":"Write Only");row("AUTHLIM",String(p.authLimit));row("Config",p.configLocked?"Locked":"Open");char pwd[16];snprintf(pwd,sizeof(pwd),"%02X %02X %02X %02X",p.pwd[0],p.pwd[1],p.pwd[2],p.pwd[3]);row("PWD",pwd);char pack[8];snprintf(pack,sizeof(pack),"%02X %02X",p.pack[0],p.pack[1]);row("PACK",pack);_passwordList.resetScroll();_passwordList.setRows(_passwordRows,_passwordCount);render();}
void HfDumpFormScreen::setPassword(){const auto cur=HfDumpParser::inspectPassword(_dump,_dumpLen);if(!cur.supported){rebuild();ShowStatusAction::show("Password not supported",1600);return;}if(cur.configLocked){rebuild();ShowStatusAction::show("Configuration locked",1600);return;}String pt=InputTextAction::popup("Password","",InputTextAction::INPUT_TEXT);if(InputTextAction::wasCancelled()){rebuild();return;}uint8_t pwd[4];if(!passwordFromText(pt,pwd)){rebuild();ShowStatusAction::show("Password required",1600);return;}String kt=InputTextAction::popup("PACK (4 hex)","",InputTextAction::INPUT_HEX);if(InputTextAction::wasCancelled()){rebuild();return;}uint8_t pack[2];if(!parseHex(kt,pack,2)){rebuild();ShowStatusAction::show("PACK must be 4 hex digits",1600);return;}static const InputSelectAction::Option modes[]={{"Write Only","w"},{"Read & Write","rw"}};const char*m=InputSelectAction::popup("Protection",modes,2,nullptr);if(!m){rebuild();return;}bool ok=HfDumpParser::setPassword(_dump,_dumpLen,pwd,pack,strcmp(m,"rw")==0);if(ok)_info=HfDumpParser::inspect(_dump,_dumpLen);rebuild();ShowStatusAction::show(ok?"Password set":"Failed",1600);}
void HfDumpFormScreen::removePassword(){const auto cur=HfDumpParser::inspectPassword(_dump,_dumpLen);if(!cur.supported){rebuild();ShowStatusAction::show("Password not supported",1600);return;}if(cur.configLocked){rebuild();ShowStatusAction::show("Configuration locked",1600);return;}if(!cur.enabled){rebuild();ShowStatusAction::show("Password not set", 1500);return;}bool ok=HfDumpParser::removePassword(_dump,_dumpLen);if(ok)_info=HfDumpParser::inspect(_dump,_dumpLen);rebuild();ShowStatusAction::show(ok?"Password removed":"Failed",1600);}
String HfDumpFormScreen::suggestedName()const{return String(shortType(_info.type))+"_"+uidText();}
bool HfDumpFormScreen::writeFile(const String&p){fs::File f=Uni.Storage->open(p.c_str(),"w");if(!f)return false;size_t n=f.write(_dump,_dumpLen);f.close();return n==_dumpLen;}
void HfDumpFormScreen::save(){if(_uidSource==UID_SAVED&&!_uidFile.length()){rebuild();ShowStatusAction::show("Select UID file",1600);return;}if(_ndefSource==NDEF_SAVED&&!_ndefFile.length()){rebuild();ShowStatusAction::show("Select NDEF file",1600);return;}if(!Uni.Storage||!Uni.Storage->isAvailable()){ShowStatusAction::show("Storage unavailable",1600);return;}if(!_dump||!_dumpLen)return;String p=_path;if(!p.length()){String n=InputTextAction::popup("Save Dump",suggestedName().c_str());if(InputTextAction::wasCancelled()){rebuild();return;}String b=clean(n);if(!b.length()){rebuild();ShowStatusAction::show("Invalid file name",1600);return;}Uni.Storage->makeDir("/unigeek/nfc");Uni.Storage->makeDir("/unigeek/nfc/dumps");p=uniquePath("/unigeek/nfc/dumps",b);if(!p.length()){rebuild();ShowStatusAction::show("Failed",1600);return;}}bool ok=writeFile(p);if(ok)_path=p;rebuild();ShowStatusAction::show(ok?("Saved: "+bn(p)).c_str():"Failed",1600);}
bool HfDumpFormScreen::receiveNdef(void* context,const uint8_t* ndef,size_t len){auto*self=static_cast<HfDumpFormScreen*>(context);if(!self||!ndef||!len||len>sizeof(self->_ndef))return false;if(!HfDumpParser::replaceNdef(self->_dump,self->_dumpLen,ndef,len))return false;memcpy(self->_ndef,ndef,len);self->_ndefLen=len;self->_ndefFile="";self->_ndefSource=NDEF_NEW;self->_info=HfDumpParser::inspect(self->_dump,self->_dumpLen);self->rebuild();return true;}
void HfDumpFormScreen::onItemSelected(uint8_t i){if(_state==TYPE_SELECT){_selectedIndex=0;if(rebuildForType(i))rebuild();else{rebuild();ShowStatusAction::show("Failed",1600);}return;}if(_state==UID_SOURCE_SELECT){_selectedIndex=1;UidSource previous=_uidSource;bool existing=(_mode!=NEW_ITEM||_path.length()||_uidSource==UID_CURRENT);_uidSource=existing?(i==0?UID_CURRENT:i==1?UID_RANDOM:i==2?UID_SAVED:UID_MANUAL):(i==0?UID_RANDOM:i==1?UID_SAVED:UID_MANUAL);bool uidFailed=false;if(_uidSource==UID_RANDOM){uint8_t old[10]={};memcpy(old,_uid,_uidLen);randomUid();if(applyUid())_info=HfDumpParser::inspect(_dump,_dumpLen);else{memcpy(_uid,old,_uidLen);_uidSource=previous;uidFailed=true;}}if(_uidSource==UID_SAVED){_uidFile="";}rebuild();if(uidFailed)ShowStatusAction::show("UID format not supported",1600);return;}if(_state==UID_FILE_SELECT){if(i>=_browser.count())return;auto e=_browser.entry(i);if(e.isDir){_uidPickDir=e.path;browseUid();return;}uint8_t u[10];size_t n=0;if(!IdentityFile::loadNfcUid(e.path,u,sizeof(u),n)||n!=_uidLen){ShowStatusAction::show("UID length mismatch",1600);return;}uint8_t old[10]={};memcpy(old,_uid,_uidLen);memcpy(_uid,u,n);if(!applyUid()){memcpy(_uid,old,_uidLen);rebuild();ShowStatusAction::show("UID format not supported",1600);return;}_uidFile=e.path;_info=HfDumpParser::inspect(_dump,_dumpLen);_selectedIndex=2;rebuild();return;}if(_state==NDEF_SOURCE_SELECT){_selectedIndex=2+(_uidSource==UID_SAVED||_uidSource==UID_MANUAL||_uidSource==UID_CURRENT?1:0);bool existing=(_mode!=NEW_ITEM||_path.length()||_ndefSource==NDEF_CURRENT);NdefSource next=existing?(i==0?NDEF_CURRENT:i==1?NDEF_NONE:i==2?NDEF_SAVED:NDEF_NEW):(i==0?NDEF_NONE:i==1?NDEF_SAVED:NDEF_NEW);if(next==NDEF_NONE){if(HfDumpParser::replaceNdef(_dump,_dumpLen,nullptr,0)){_ndefSource=NDEF_NONE;_ndefLen=0;_ndefFile="";_info=HfDumpParser::inspect(_dump,_dumpLen);rebuild();}else{rebuild();ShowStatusAction::show("Failed to clear NDEF",1600);}}else if(next==NDEF_SAVED){_ndefSource=NDEF_SAVED;_ndefFile="";rebuild();}else if(next==NDEF_NEW){Screen.push(new NdefRecordFormScreen(NdefRecordFormScreen::BUFFER,"",&HfDumpFormScreen::receiveNdef,this));}else{_ndefSource=NDEF_CURRENT;rebuild();}return;}if(_state==NDEF_FILE_SELECT){if(i>=_browser.count())return;auto e=_browser.entry(i);if(e.isDir){_ndefPickDir=e.path;browseNdef();return;}fs::File f=Uni.Storage->open(e.path.c_str(),"r");if(!f||f.size()==0||f.size()>sizeof(_ndef)){if(f)f.close();ShowStatusAction::show("Invalid NDEF file",1600);return;}const size_t fileLen=f.size();uint8_t candidate[sizeof(_ndef)];const size_t got=f.read(candidate,fileLen);f.close();if(got!=fileLen||!NdefRecordFormScreen::isValidSingleRecord(candidate,got)){ShowStatusAction::show("Invalid NDEF record",1600);return;}if(!HfDumpParser::replaceNdef(_dump,_dumpLen,candidate,got)){ShowStatusAction::show("NDEF does not fit",1600);return;}memcpy(_ndef,candidate,got);_ndefLen=got;_ndefFile=e.path;_ndefSource=NDEF_SAVED;_info=HfDumpParser::inspect(_dump,_dumpLen);_selectedIndex=3+(_uidSource==UID_SAVED||_uidSource==UID_MANUAL||_uidSource==UID_CURRENT?1:0);rebuild();return;}uint8_t r=0;if(i==r++){selectType();return;}if(i==r++){selectUidSource();return;}if(_uidSource==UID_SAVED){if(i==r++){browseUid();return;}}if(_uidSource==UID_MANUAL){if(i==r++){editUid();return;}}else if(_uidSource==UID_CURRENT){if(i==r++)return;}if(i==r++){selectNdefSource();return;}if(_ndefSource==NDEF_SAVED){if(i==r++){browseNdef();return;}}if(i==r++){viewMemory();return;}if(i==r++){editMemory();return;}if(HfDumpParser::isType2(_info.type)){if(i==r++){showPasswordInfo();return;}if(i==r++){setPassword();return;}if(i==r++){removePassword();return;}}if(i==r)save();}
